typedef unsigned int big_int;
typedef unsigned int size_t;
extern "C" size_t strlen(const char *);

class stringx;
class string_buf {
  friend class stringx;
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};
class stringx {
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
  char *chars;
  string_buf *my_buf;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  void append(const char*, int = -1);
  void append(const stringx&);
  void make_room(int);
};
inline stringx operator+(const stringx& lhs, const stringx& rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const stringx& lhs, const char* rhs) {
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}
extern void error(const stringx&);

class script_object_instance { stringx name; public: const stringx& get_name() const { return name; } };
class vm_executable { stringx name; stringx fullname; public: const stringx& get_fullname() const { return fullname; } };
class vm_thread {
  script_object_instance *inst;
  const vm_executable *ex;
public:
  script_object_instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};
class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  void pop(int n) { SP += -n; }
  vm_thread *get_thread() const { return my_thread; }
  bool push(const char*, int);
};
typedef float vm_num_t;
struct vector3d { float x, y, z; };
inline float dot(const vector3d& a, const vector3d& b) { float t = a.x*b.x + a.y*b.y + a.z*b.z; return t; }

class slf_dot3_t {
public:
  enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  struct parms_t { vector3d v1; vector3d v2; };
  bool operator()(vm_stack& stack, entry_t entry);
};
extern "C" bool candidate(slf_dot3_t*, vm_stack&, slf_dot3_t::entry_t)
  __asm__("__cl__10slf_dot3_tR8vm_stackQ320script_library_class8function7entry_t");
bool slf_dot3_t::operator()(vm_stack& stack, entry_t entry)
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  vm_num_t result = dot(parms->v1,parms->v2);
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
